{
  "book_code": "JASHER",
  "verses": [
    {
      "chapter": 2,
      "verse": 15,
      "text_ar": "وعندما كان كاينان في السنّ السبعين، أنجب ثلاثة أبناء واثنتين بنات."
    },
    {
      "chapter": 2,
      "verse": 16,
      "text_ar": "وهؤلاء هي أسماء أولاد كاينان: اسم البكر ملاعل، والثاني إينان، والثالث مريد، وكانت أخواتهم عاداه وزيلة؛ هؤلاء هم الخمسة أبناء كاينان الذين وُلدوا له."
    },
    {
      "chapter": 2,
      "verse": 17,
      "text_ar": "ولاميك، ابن ميثوسائيل، ارتبط بقاينان بالزواج، فأخذ بناتهما زوجتين، فحملت عاداه وأنجبت لاميك صبيًا، فسماه جبال."
    },
    {
      "chapter": 2,
      "verse": 18,
      "text_ar": "وحملت مرة أخرى وأنجبت صبيًا، فأسمته جوبال؛ وزيلة، أختها، كانت عاقرًا في ذلك الزمان ولم يكن لها نسل."
    },
    {
      "chapter": 2,
      "verse": 19,
      "text_ar": "ففي ذلك الزمان بدأ أبناء البشر يخونون الله، ويعصون الوصايا التي أمرها لآدم، أن يثمروا ويتكاثروا في الأرض."
    },
    {
      "chapter": 2,
      "verse": 20,
      "text_ar": "وبعض أبناء البشر جعلوا زوجاتهم يشربن جرعة تجعلهن عاقرات، كي يحافظن على أجسامهن ولا يبهت جمالهن."
    },
    {
      "chapter": 2,
      "verse": 21,
      "text_ar": "وعندما جعل أبناء البشر بعض زوجاتهم يشربن، شربت زيلة معهن."
    },
    {
      "chapter": 2,
      "verse": 22,
      "text_ar": "وكانت النساء الحوامل يبدين مكروهات في نظر أزواجهن كالأرامل بينما أزواجهن على قيد الحياة، لأنهن كن مرتبطات بالعرجات فقط."
    },
    {
      "chapter": 2,
      "verse": 23,
      "text_ar": "وفي آخر الأيام والسنوات، عندما كبرت زيلة، فتح الله بطنها."
    },
    {
      "chapter": 2,
      "verse": 24,
      "text_ar": "وحملت وأنجبت صبيًا فأسمته طوبال كاين، قائلة: بعد أن ذبلتُ قد حصلتُ عليه من الإله القدير."
    }
  ]
}
